import { ReactElement, useState } from "react";
import { Link } from "react-router-dom";
import {
  Disclosure,
  DisclosureButton,
  DisclosurePanel,
} from "@headlessui/react";
import logo from "../../assets/images/logo.png";
import cx from "classnames";
import BreadCrumb from "./BreadCrumb";
import UserProfile from "./UserProfile";
import LanguageSelect from "./LanguageSelect";
import { useTranslate } from "../../utils/locales/use-locales";
import Icon from "@components/core-components/icon";

export default function DashboardLayout({ children }: any) {
  const { t } = useTranslate();
  const [navColapssed, setNavCollapsed] = useState<boolean>(false);

  interface NavigationItem {
    name: string;
    href?: string;
    icon: ReactElement;
    current: boolean;
    children?: { name: string; href?: string }[];
  }

  const navigation: NavigationItem[] = [
    {
      name: t("menuItems.dashboard"),
      href: "#",
      icon: <Icon iconName="categoryIcon2" className="h-6 w-6 shrink-0" />,
      current: true,
    },
    {
      name: t("menuItems.players"),
      icon: <Icon iconName="players" className="h-6 w-6 shrink-0" />,
      current: false,
      children: [{ name: t("menuItems.engineering"), href: "/management/players/list" }],
    },
    {
      name: t("menuItems.reports"),
      icon: <Icon iconName="report" className="h-6 w-6 shrink-0" />,
      current: false,
    },
    {
      name: t("menuItems.payment"),
      href: "#",
      icon: <Icon iconName="payment" className="h-6 w-6 shrink-0" />,
      current: false,
    },
    {
      name: t("menuItems.promotionalTools"),
      href: "#",
      icon: <Icon iconName="promotion" className="h-6 w-6 shrink-0" />,
      current: false,
    },
    {
      name: t("menuItems.sportsbook"),
      href: "#",
      icon: <Icon iconName="bookOpen" className="h-6 w-6 shrink-0" />,
      current: false,
    },
    {
      name: t("menuItems.userManagements"),
      href: "#",
      icon: <Icon iconName="userPen" className="h-6 w-6 shrink-0" />,
      current: false,
    },
    {
      name: t("menuItems.tools"),
      href: "#",
      icon: <Icon iconName="settings" className="h-6 w-6 shrink-0" />,
      current: false,
    },
  ];

  // const mainclassNames = cx(
  //   "flex flex-col h-screen bg-gray-900 p-6 overflow-y-auto relative transition-width duration-500",
  //   {
  //     "w-[84px]": navColapssed,
  //     "w-[253px]": !navColapssed,
  //   }
  // );
  const sidebarClassNames = cx(
    "fixed top-0 left-0 h-full bg-gray-900 p-6 overflow-y-auto transition-width duration-500",
    {
      "w-[84px]": navColapssed,
      "w-[253px]": !navColapssed,
    }
  );

  // Class for the main content area with dynamic margin-left
  const contentClassNames = cx(
    "flex-grow flex flex-col relative h-screen transition-all duration-500 pl-10 pr-10 py-8",
    {
      "ml-[80px]": navColapssed,
      "ml-[215px]": !navColapssed,
    }
  );

  const anchorClassName = cx(
    " flex flex-row items-center group gap-x-3 rounded-md p-2 text-sm font-normal leading-6 text-gray-400 hover:text-white hover:bg-primary whitespace-nowrap",
    {
      "w-[50px] justify-center": navColapssed,
    }
  );

  const disclosureButtonClassNames = cx(
    "flex flex-row items-center group w-full gap-x-3 rounded-md p-2 text-left text-sm font-normal leading-6 text-gray-400 hover:text-white hover:bg-primary",
    {
      "w-[50px] justify-center": navColapssed,
    }
  );

  const collapseIconClassNames = cx(
    "transform transition-transform duration-500",
    {
      "rotate-180": navColapssed,
    }
  );

  const handleCollapse = (e: React.MouseEvent<HTMLDivElement>) => {
    e.stopPropagation();
    setNavCollapsed(!navColapssed);
  };

  return (
    <div className="flex  flex-row bg-gray-200 ">
      <div className={sidebarClassNames}>
        <div className="mb-10 ">
          {navColapssed ? (
            <Icon
              iconName="logo"
              className=" shrink-0"
              svgProps={{ width: 36, height: 28 }}
            />
          ) : (
            <img src={logo} style={{ width: "161px", height: "39px" }} />
          )}
        </div>

        <nav className="flex  flex-1 flex-col">
          <ul role="list" className="flex flex-1 flex-col gap-y-7">
            <li>
              <ul role="list" className="-mx-2 space-y-1">
                {navigation.map((item) => (
                  <li key={item.name}>
                    {!item.children ? (
                      <Link to={item.href ?? "#"} className={anchorClassName}>
                        {item.icon}
                        {!navColapssed && item.name}
                      </Link>
                    ) : (
                      <Disclosure as="div">
                        <DisclosureButton
                          className={disclosureButtonClassNames}
                        >
                          {item.icon}
                          {!navColapssed && item.name}
                          {!navColapssed && (
                            <Icon
                              iconName="rightArrow"
                              svgProps={{ width: 18, height: 18 }}
                              className="ml-auto h-5 w-5 shrink-0 only:group-data-[open]:rotate-90 group-data-[open]:text-gray-500"
                            />
                          )}
                        </DisclosureButton>
                        <DisclosurePanel as="ul" className="mt-1 px-2">
                          {item.children.map((subItem) => (
                            <li key={subItem.name}>
                              <DisclosureButton
                                as={Link}
                                to={subItem.href ?? "#"}
                                className="block rounded-md py-2 pl-9 pr-2 text-sm leading-6 text-gray-400 hover:text-white font-normal"
                              >
                                {subItem.name}
                              </DisclosureButton>
                            </li>
                          ))}
                        </DisclosurePanel>
                      </Disclosure>
                    )}
                  </li>
                ))}
              </ul>
            </li>
          </ul>
        </nav>
      </div>
      {/* main content */}

      <div className={contentClassNames}>
        <div
          onClick={handleCollapse}
          className={cx(
            "bg-white flex z-50 fixed top-[40px] left-[-5px] flex-col items-center justify-center text-gray-900 w-[27px] h-[27px] border border-gray-400 rounded-lg	 cursor-pointer  transition-all duration-500",
            {
              "left-[66px]": navColapssed,
              "left-[240px]": !navColapssed,
            }
          )}
        >
          <Icon
            iconName="leftArrow"
            iconClass="text-gray-900"
            className={collapseIconClassNames}
            svgProps={{ width: 10, height: 10 }}
          />
        </div>
        <div className="box-border h-16 flex items-center bg-white pl-10 justify-between">
          <BreadCrumb />
          <div className="flex items-center">
            <LanguageSelect />
            <UserProfile />
          </div>
        </div>
        <div className="flex-grow  pl-10 pr-10 py-8">{children}</div>
      </div>
    </div>
  );
}
