import logo from "../../../assets/images/logo-dark.png";
import { Link } from "react-router-dom";
import PInput from "@components/core-components/input";
import { useForm, SubmitHandler } from "react-hook-form";
import * as yup from "yup";
import { yupResolver } from "@hookform/resolvers/yup";
import authService from "api/auth/AuthService";
import { useAppDispatch } from "hooks/redux";
import { authenticationLogin } from "store/auth/authenticationSlice";

const schema = yup.object().shape({
  userId: yup
    .string()
    .required("userId is required"),
  password: yup.string().required("Password is required"),
});

interface IFormInput {
  userId: string;
  password: string;
}

const Login = () => {
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<IFormInput>({
    resolver: yupResolver(schema),
  });

  const dispatch = useAppDispatch();

  const onSubmit: SubmitHandler<IFormInput> = (data: any) => {
    dispatch(authenticationLogin(data));
  };

  return (
    <>
      <div className="flex justify-center h-screen">
        <div className="flex items-center flex-col md:w-[380px] mt-[170px] ">
          <div>
            <img src={logo} width={253} height={75} />
          </div>
          <div className="my-12">
            <h1 className="text-heading-24 text-dark font-medium">
              Sign in to your account
            </h1>
          </div>
          <form onSubmit={handleSubmit(onSubmit)} className="w-full">
            <PInput
              placeholder="User ID"
              id="userId"
              type="userId"
              register={register}
              error={errors.userId}
              className="w-full text-body-reg-13 h-[42px]"
            />
            <PInput
              placeholder="Password"
              id="password"
              type="password"
              register={register}
              error={errors.password}
              className="w-full text-body-reg-13 h-[42px]"
            />
            <div className="flex justify-end w-full">
              <Link
                className="text-primary underline font-semibold text-body-reg-14"
                to="#"
              >
                Forgot password
              </Link>
            </div>
            <button
              type="submit"
              className="bg-primary text-white font-semibold rounded-md mt-4 hover:bg-primary-dark transition-colors focus:outline-none focus:ring-2 focus:ring-indigo-400 h-[45px] w-full text-body-reg-13"
            >
              SIGN IN
            </button>
          </form>
        </div>
      </div>
    </>
  );
};

export default Login;
